TLM.f("Tempora/Epi2-3",{"officium":"Feria IV infra Hebdomadam II post Epiphaniam","rule":["vide Epi2-0","Suffragium=Maria2;Papa,Ecclesiæ;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate"],"fallback":"Tempora/Epi2-0","from":{"Introitus":"Tempora/Epi2-0","Oratio":"Tempora/Epi2-0","Lectio":"Tempora/Epi2-0","Graduale":"Tempora/Epi2-0","Evangelium":"Tempora/Epi2-0","Offertorium":"Tempora/Epi2-0","Secreta":"Tempora/Epi2-0","Communio":"Tempora/Epi2-0","Postcommunio":"Tempora/Epi2-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 65:4"},{"k":"text","la":"Omnis terra adóret te, Deus, et psallat tibi: psalmum dicat nómini tuo, Altíssime."},{"k":"ref","la":"Ps 65:1-2"},{"k":"text","la":"Jubiláte Deo, omnis terra, psalmum dícite nómini ejus: date glóriam laudi ejus."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Omnis terra adóret te, Deus, et psallat tibi: psalmum dicat nómini tuo, Altíssime."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, qui cœléstia simul et terréna moderáris: supplicatiónes pópuli tui cleménter exáudi; et pacem tuam nostris concéde tempóribus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Romános."},{"k":"ref","la":"Rom 12:6-16"},{"k":"text","la":"Fratres: Habéntes donatiónes secúndum grátiam, quæ data est nobis, differéntes: sive prophetíam secúndum ratiónem fídei, sive ministérium in ministrándo, sive qui docet in doctrína, qui exhortátur in exhortándo, qui tríbuit in simplicitáte, qui præest in sollicitúdine, qui miserétur in hilaritáte. Diléctio sine simulatióne. Odiéntes malum, adhæréntes bono: Caritáte fraternitátis ínvicem diligéntes: Honóre ínvicem præveniéntes: Sollicitúdine non pigri: Spíritu fervéntes: Dómino serviéntes: Spe gaudéntes: In tribulatióne patiéntes: Oratióni instántes: Necessitátibus sanctórum communicántes: Hospitalitátem sectántes. Benedícite persequéntibus vos: benedícite, et nolíte maledícere. Gaudére cum gaudéntibus, flere cum fléntibus: Idípsum ínvicem sentiéntes: Non alta sapiéntes, sed humílibus consentiéntes."}],"Graduale":[{"k":"ref","la":"Ps 106:20-21"},{"k":"text","la":"Misit Dóminus verbum suum, et sanávit eos: et erípuit eos de intéritu eórum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus: et mirabília ejus fíliis hóminum. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 148:2"},{"k":"text","la":"Laudáte Dóminum, omnes Angeli ejus: laudáte eum, omnes virtútes ejus. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem."},{"k":"ref","la":"Joann 2:1-11"},{"k":"text","la":"In illo témpore: Núptiæ factæ sunt in Cana Galilǽæ: et erat Mater Jesu ibi. Vocátus est autem et Jesus, et discípuli ejus ad núptias. Et deficiénte vino, dicit Mater Jesu ad eum: Vinum non habent. Et dicit ei Jesus: Quid mihi et tibi est, mulier? nondum venit hora mea. Dicit Mater ejus minístris: Quodcúmque díxerit vobis, fácite. Erant autem ibi lapídeæ hýdriæ sex pósitæ secúndum purificatiónem Judæórum, capiéntes síngulæ metrétas binas vel ternas. Dicit eis Jesus: Implete hýdrias aqua. Et implevérunt eas usque ad summum. Et dicit eis Jesus: Hauríte nunc, et ferte architriclíno. Et tulérunt. Ut autem gustávit architriclínus aquam vinum fáctam, et non sciébat unde esset, minístri autem sciébant, qui háuserant aquam: vocat sponsum architriclínus, et dicit ei: Omnis homo primum bonum vinum ponit: et cum inebriáti fúerint, tunc id, quod detérius est. Tu autem servásti bonum vinum usque adhuc. Hoc fecit inítium signórum Jesus in Cana Galilǽæ: et manifestávit glóriam suam, et credidérunt in eum discípuli ejus."}],"Offertorium":[{"k":"ref","la":"Ps 65:1-2; 65:16"},{"k":"text","la":"Jubiláte Deo, univérsa terra: psalmum dícite nómini ejus: veníte et audíte, et narrábo vobis, omnes qui timétis Deum, quanta fecit Dóminus ánimæ meæ, allelúja."}],"Secreta":[{"k":"text","la":"Oblata, Dómine, múnera sanctífica: nosque a peccatórum nostrórum máculis emúnda."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Joann 2:7; 2:8; 2:9; 2:10-11"},{"k":"text","la":"Dicit Dóminus: Implete hýdrias aqua et ferte architriclíno. Cum gustásset architriclínus aquam vinum factam, dicit sponso: Servásti bonum vinum usque adhuc. Hoc signum fecit Jesus primum coram discípulis suis."}],"Postcommunio":[{"k":"text","la":"Augeátur in nobis, quǽsumus, Dómine, tuæ virtútis operatio: ut divínis vegetáti sacraméntis, ad eórum promíssa capiénda, tuo múnere præparémur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3267018770fb7d51":{"t":"Ps 65, 4, Ps 65, 1-2\n(Ps 65, 4) Sva zemlja neka ti se, Bože, klanja i neka ti pjeva. Neka pjeva imenu tvojemu, Višnji. (Ps 65, 1-2) Kličite Bogu svi narodi, pjevajte psalme njegovu imenu, hvalite njegovu slavu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 65, 4) Sva zemlja neka ti se, Bože, klanja i neka ti pjeva. Neka pjeva imenu tvojemu, Višnji.","kn":"(Ps, 65, 4). Sva zemlja neka Ti se klanja, Bože, i neka pjeva Tebi, neka pjeva psalme imenu Tvoijemu, Višnji! (Ps. 65. 1, 2) Poklikni Bogu sva zemljo, pjevajte psalme imenu njegovu, dajte mu hvalu sa slavom! Slava Ocu . . . Sva zemlja . . .","knRef":"Kniewald 1942, str. 76–77 (snimka 39) (OCR)"},"a3462e1391d73979":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, koji upravljaš i nebeskim i zemaljskim stvarima, milostivo usliši molbe puka svoga i podaj svoj mir u naša vremena.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući, vječni Bože, koji upravljaš i nebes;kipi i ze^maljskim stvarima, usliši milostivo mO'litve puka svoga i podaj mir svoj vremenima našim, po G. n. I. K.","knRef":"Kniewald 1942, str. 76–77 (snimka 39) (OCR)"},"db62595357017297":{"t":"Rim 12, 6-16\nČitanje Poslanice bl. Pavla apostola Rimljanima. Braćo: Prema danoj nam milosti imamo različite darove. Tko ima dar proroštva, neka proriče u skladu s vjerovanjem; tko ima dar službe, neka služi; tko ima dar pouke, neka poučava; tko ima dar utjehe, neka tješi; tko dijeli, neka dijeli iskreno; tko upravlja, neka upravlja brižno; tko iskazuje milosrđe, neka to čini radosno. – Ljubav neka bude bez pretvaranja. Mrzite zlo, držite se dobra. Ljubite se među sobom bratskom ljubavlju, u časti dajte prednost jedan drugom. U brizi ne budite lijeni, budite gorljivi duhom u Gospodnjoj službi. U nadi se radujte, budite strpljivi u nevolji, postojani u molitvi. Pomažite svetima u potrebama, budite gostoljubivi. Blagoslivljajte one koji vas progone, blagoslivljajte, a nemojte proklinjati. Radujte se s onima koji se raduju, plačite s onima koji plaču. Budite jedne misli među sobom. Ne težite za visokim stvarima, nego se zadovoljite neznatnima.","kn":"čitanje poslanice bi. Pavla apostola Rimljanima (12, 6-16). Braćo! Imamo različite .darove prema mi- losti, koja nam je dana: Ako koji ima proroštvo, neka bude po mjeri vjere; ako službu, neka služi; ako je koji učitelj, neka uči; ako opominje, neka cp.ominje; koji daje, neka daje iskreno; koji upravlja, neka to čini brižno; koji iskazuje milosrđe, neka čini s veseljem. Ljubav neka bude nehinjena. Mrzite zlo, držite se dobra. Ljubite jedan drugoga bratskom ljubavlju, pretječite jedan drugoga sa štovanjem, u skrbi ne budite lijeni, revnujte duhovno, služite Gospodinu, radujte se u nadi, u nevolji budite strpljivi, u molitvi postojani. Svetima pomažite u potrebama, budite gostoljubljivi, blagoslivljajte one, ^ koji vas progone, blagoslivljajte, a nemojte proklinjati. Radujte se s onima, koji se raduju, a plačite s onima, koji plaču. Jednako mislite među sobom. Ne težite za visokim stvarima, nego se zadovoljite neznatnima. i","knRef":"Kniewald 1942, str. 76–77 (snimka 39) (OCR)"},"2988097cec4e6315":{"t":"Ps 106, 20-21\nPoslao je Gospodin svoju riječ i ozdravio ih i izbavio ih od propasti. Neka slavi Gospodina milosrđe njegovo i njegova čudesa na sinovima ljudskim.\n\nPs 148, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nHvalite Gospodina, svi anđeli njegovi, hvalite ga, sve čete njegove. <i>Aleluja</i>.","kn":"(Ps. 106, 20, 21). Posla Gospodin Riječ svoju i isaijeli ih i izbavi ih od pogibli. Zato neka slave milosrđe Gospodnje i divna, djela njegova nad sinovima ljudskim.\n\nAleluja, aleluja. (Ps. 48, 2) Hvalite Gospodina svi anđeli njegovi, hvalite ga sve nebeske sile njegove, aleluja.","knRef":"Kniewald 1942, str. 78–79 (snimka 40) (OCR)"},"9fb3d2b5b81f0585":{"t":"Iv 2, 1-11\nSlijedi sveto Evanđelje po Ivanu. U ono vrijeme bio je u Kani Galilejskoj pir, a bila je ondje i Isusova majka. A na pir je bio pozvan Isus i njegovi učenici. Kad je nestalo vina, reče Isusu njegova majka: Vina nemaju. A Isus joj reče: Što je meni i tebi, ženo? Još nije došao moj čas. Tada njegova majka reče slugama: Što god vam rekne učinite. Ondje je bilo šest kamenih posuda, svaka od dvije do tri mjere, za pranje Židovima. Isus im reče: Napunite posude vodom. Oni ih napune do vrha. Tada im reče: Sad zagrabite i odnesite ravnatelju stola. Oni odnesu. Kad ravnatelj stola okusi vodu pretvorenu u vino a nije znao odakle je, dok su sluge koji zagrabiše vodu znali, ravnatelj stola zovne mladoženju i reče mu: Svatko iznosi najprije dobro vino, a kad se gosti ponapiju, onda slabije, ti si pak dobro vino čuvao do sada. Tako učini Isus prvo čudo u Kani Galilejskoj i objavi svoju slavu te su njegovi učenici vjerovali u njega.","kn":"t Slijedi sveto evanđelje po Ivanu (2, 1-11). U ono vrijeme bila je svadba u Kani Galilejskoj i bila, je ondje Isusova majka. A bio je gpozvan ,na svadbu i Isus i njegovi učenici. I kad je nestalo vina, reče Isusu njegova majka; Nemaju vina! A Isus joj reče: Sto je meni i tebi, ženo? Još nije došao moj čas. Njegova majka reče slugama: Učinite, štogod vam rekne! A stajalo je ondje šest ka- ''isokim položajem. Ne prczirite malene i neznatne stvari, poslove, položaj. menih sudova za vodu, koji su bili postavljeni za židovsko čišćenje i svaki je hvatao po dvije ili tri mjere. Isus im reče: Napunite sudove vodom! I napuniše ih do vrha. Nato im reče Isus: Sada zahvatite i nosite nadstojniku stola. I odnijeli su. A kad na'dstoj.niik stola Okusi vino, koje je postalo od vode, jer nije znao, otkuda je, a sluge, koji su zagrabili vodu, znali su, nadstojnik stola pozove mladoženju i reče mu; Svaki čovjek iznosi najprije dobro vino, a kad se ponapiju, onda slabije, a ti si čuvao dobro vino .sve do sada. Ovaj početak čudesa učini Isus u Kani Galilejskoj, i objavi svoju slavu, i njegovi učenici povjerovaše u njega.","knRef":"Kniewald 1942, str. 78–79 (snimka 40) (OCR)"},"9c5bfd653e4c1dae":{"t":"Ps 65, 1-2 i 16\nKličite Bogu svi narodi, pjevajte psalme njegovu imenu. Dođite i slušajte svi koji se Boga bojite, pa ću vam pričati što je sve učinio mojoj duši, aleluja.","kn":"(Ps. 65, 1, 12, 16). Pokiikni Bogu sva zemljo, pjevajte pjesmu imenu njegovu; dođite i slušajte svi, koji se Bogai bojite, i kazivat ću vam, koliko Gospodin učini duši mojoj. Aleluja.","knRef":"Kniewald 1942, str. 326–327 (snimka 164) (OCR)"},"ab9e9caa9afb15da":{"t":"Posveti, Gospodine, prikazane darove, a nas od ljage naših grijeha očisti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posveti, Gospodine, prikazane darove, a nas očisti od ljage grijeha naših, po G. n. I. K.","knRef":"Kniewald 1942, str. 78–79 (snimka 40) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"ed31f706d3b5b6d2":{"t":"Iv 2, 7 i 8 i 9 i 10 i 11\nGospodin reče: »Napunite posude i odnesite ravnatelju stola.« A kad ovaj okusi vodu pretvorenu u vino, reče mladoženji: »Čuvao si dobro vino do sada.« To je prvo čudo što ga učini Isus pred svojim učenicima.","kn":"(IV. 2, 7-11). Reče Gospodin: Napunite vrčeve vodom i nosite nadstojniku stola! A kad je nadstojnik stola okusio od vode, koja je postala vino, reče mladoženji; čuvao si dobro vino do sada. Ovo učini Isus početak čudesima pred svojim uče- Hicima.","knRef":"Kniewald 1942, str. 78–79 (snimka 40) (OCR)"},"d4c152e2efb613a2":{"t":"<i>Pomolimo se</i>.\nUmnoži u nama, molimo, Gospodine, djelovanje svoje moći da se, okrijepljeni božanskim otajstvima, po tvojem daru pripravimo da primimo ono što obećavaju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo Te, Gospodine, umnoži nama djelovanje svoje moči, da se okrijefpljeni božanskim otajstvima pripravimo po Tvojoj milosti primiti ono, što obećavaju, po G. n. I. K IsUs je voljan očistiti me od grijeha moćnom svojom riječi — samo ako ja hoću. Hoću li doista da se riješim grijeha i bližnje grješne prigode?","knRef":"Kniewald 1942, str. 78–79 (snimka 40) (OCR)"}}});
